// Shared DOM-apply path for new public messages — called by the polling
// success handler below and by the websocket transport (js/ws.js).
applyPublicLogs = function (mLogs, mLast) {
    // numeric compare — the poll response carries post ids as strings and
    // a string-vs-string ">" would be lexicographic ("100" < "99")
    mLast = parseInt(mLast, 10) || 0;
    if (typeof wsEnabled !== 'undefined' && wsEnabled) {
        // poll/socket race can deliver the same post twice — drop
        // already-rendered ids before appending
        var frag = $('<ul>' + mLogs + '</ul>');
        frag.children('li[id]').each(function () {
            if (document.getElementById(this.id)) {
                $(this).remove();
            }
        });
        mLogs = frag.html();
        if (!mLogs) {
            if (mLast > parseInt(lastPost, 10)) {
                lastPost = mLast;
            }
            return;
        }
    }
    $("#show_chat ul").append(mLogs);
    if (mLogs.indexOf("my_notice") >= 1 && fload == 1 && uSound == 2) {
        usernamePlay();
    }
    if (fload == 1 && uSound == 2) {
        messagePlay();
    }
    if (focused == false) {
        PageTitleNotification.Off();
        PageTitleNotification.On(system.newMessage);
    }
    if (mLast > parseInt(lastPost, 10)) {
        lastPost = mLast;
    }
    scrollIt(fload);
    fload = 1;
}
applyDeletes = function (ids) {
