}
// Single owner of the poll timer. While the websocket transport is
// connected (wsActive) the poll is demoted to a slow safety net; js/ws.js
// re-arms on connect/disconnect. Must stay routed through here —
// innactiveControl re-arms on every poll response.
var chatLog = null;
armPolling = function (ms) {
    clearInterval(chatLog);
    chatLog = null;
    if (typeof wsEnabled !== 'undefined' && wsEnabled && wsActive) {
        // websocket mode: ZERO chat_log.php requests while the socket is
        // healthy — no timer at all. js/ws.js re-arms fast polling on
        // disconnect/connect_error.
        actSpeed = 0;
        return;
    }
    chatLog = setInterval(chat_reload, ms);
    actSpeed = ms;
}
// The remaining poll-response apply steps, factored out so the websocket
// transport (js/ws.js) drives the same DOM paths without polling.
applyLrid = function (lrid) {
    if (lrid) {
        if (lrid != lastPrivSeenInConvo) {
            $('.prlog').not('.prseen').each(function (i, c) {
                if (lrid >= $(c).data('id')) {
                    $(c).find('.msg_mark').addClass('seen_mark');
                }
            });
        }
        lastPrivSeenInConvo = lrid;
    }
}
