var waitReload = false;
var cReqId = 0;
chat_reload = function (force) {
    if (typeof wsEnabled !== 'undefined' && wsEnabled && wsActive) {
        // websocket mode never polls chat_log.php; the one forced call
        // that still matters is a private-box open (openPrivateBox sets
        // privReload) — served by system/private_box.php instead.
        if (privReload == 1 && typeof wsOpenPrivateBox === 'function') {
            wsOpenPrivateBox();
        }
        return;
    }
    if(!force && waitReload) return;

    var waiting = false;
    var cPosted = Date.now();
    var postTime = Date.now() + speed;
    var checkType = $('#main_chat_type').attr('value');
    var priv = $('#get_private').attr('value');
    logsControl();
    recalcPrivateHeight();
    waitReload = true;
    $.ajax({
        url: "system/chat_log.php",
        type: "post",
        cache: false,
        dataType: 'json',
        data: {
            fload: fload,
            caction: cAction,
            taction: tAction,
            last: lastPost,
            snum: snum,
            preload: privReload,
            priv: priv,
            lastp: lastPriv,
            pcount: pCount,
            room: user_room,
            notify: globNotify,
            token: utk,
            r: cReqId++
        },
        complete: function() {
            waitReload = false;
        },
        error: function(xhr, status, err) {
            console.log(xhr, status, err);
        },
        success: function (response) {
            if (response.check == 99 || response.check == 199) {
                if (response.check == 199) {
                    return false;
                } else if(location.hash != '#google_vignette') {
                    location.reload(true);
                    return false;
                }
            } else {
                var answerTime = Date.now();
                var mLogs = response.main_logs;
                var mLast = response.main_last;
                var sesCompare = response.ses_compare;
                var getDel = response.del;
                var checkRank = response.urank;
                var action = response.action;
                var cact = response.cact;
                var pLogs = response.priv_logs;
                var pLast = response.priv_last;
                var getPcount = response.pcount;
                var iconPrivate = response.icon_private;
                var curp = response.curp;
                var newTopic = response.topic;
                var newTaction = response.taction;
                var friendsCount = response.friends;
                var newsCount = response.news;
                var noticeCount = response.notify;
                var reportCount = response.report;
                var setroom = response.setroom;
                var useData = response.use;
                var newNotify = response.nnotif;
                var rm = response.rm;
                var lrid = response.lrid;
                balStart = response.acval;
                speed = response.speed;
                uSound = response.user_sound;
                inOut = response.acd;

                if(response.ev) {
                    eval(response.ev);
                }

                // console.log(getDel);
                applyLrid(lrid);

                if (checkRank != user_rank || action != userAction) {
                    location.reload();
                } else if (sesCompare != sesid) {
                    overWrite();
                } else if (mLogs == 99 || lastPost == mLast) {
                    scrollIt(fload);
                    if (answerTime < postTime) {
                        fload = 1;
                    }
                } else if (mLogs.indexOf("b_o_o_m") >= 1) {
                    $("#show_chat ul").html(mLogs);
                    cAction = cact;
                    lastPost = mLast;
                    fload = 1;
                } else {
                    if (answerTime < postTime) {
                        applyPublicLogs(mLogs, mLast);
                        cAction = cact;
                    }
                }
                beautyLogs();
                applyDeletes(getDel);
                if (answerTime < postTime && curp == $('#get_private').attr('value')) {
                    applyPrivateState(response.pt);
                    if (privReload == 1) {
                        applyPrivateBox(response);
                    } else {
                        if (pLogs == 99 || lastPriv == pLast) {
                            scrollPriv(privReload);
                        } else {
                            if (curp == priv) {
                                pLogs = processPrivateLogs(pLogs);
                                $("#private_content ul").append(pLogs);
                            }
                            scrollPriv(1);
                        }
                        if (getPcount !== pCount && uSound > 0) {
                            privatePlay();
                            pCount = getPcount;
                            if (focused == false) {
                                PageTitleNotification.Off();
                                PageTitleNotification.On(system.newMessage);
                            }
                        } else {
                            pCount = getPcount;
                        }
                        lastPriv = pLast;
                    }
                }
                if (answerTime < postTime) {
                    if (applyTopic(newTopic)) {
                        tAction = newTaction;
                    }
                }
                applyPrivateIcon(iconPrivate);
                if (answerTime < postTime && useData == 1) {
                    applyBadges(friendsCount, newsCount, noticeCount, reportCount);
                    grantRoom(setroom);
                    globNotify = newNotify;
                }
                if(response.ad && !window.mineralBinded) {
                    window.mineralBinded = true;
                    $(document).bind('click.mineralbox', function() {
                        event.preventDefault();
                        showMineralBox();
                        $(document).unbind('click.mineralbox');
                        window.mineralBinded = false;
                    });
                }
                if(typeof(response.vf) !== 'undefined') {
                    window.guestsShouldVerify = response.vf;
                }
                checkRm(rm);
                innactiveControl(cPosted, response.t);
                if($(window).width() < 600)
                $('.player_pad').css('margin-right', $('.container_sub_player').width() - 42);
            }
        },
    });
}
