innactiveControl = function (cPost, t) {
    // console.log(t);
    inactiveStart = 2;
    inMaxStaff = 2;
    inMaxUser = 3;
    inIncrement = 125;
    cLatency = (Date.now() - cPost);
    ac = parseInt(balStart);
    sp = parseInt(speed);
    nsp = sp + ((curActive - inactiveStart) * inIncrement);
    msp = sp * inMaxUser;
    if (boomAllow(8)) {
        msp = sp * inMaxStaff;
    }
    if (nsp > msp) {
        nsp = msp;
    }
    if (ac > 0 && curActive >= inactiveStart) {
        armPolling(nsp);
    } else {
        armPolling(sp);
    }
    $('#current_speed').text(actSpeed);
    $('#current_latency').text(cLatency);
