generateUserListEntry = function(row, user, add_class) {    
    var id = user[0];
    var name = user[1];
    if(id == user_id && fake_name) {
        name = fake_name;
    }
    var rank = user[2];
    var bot = user[3];
    var sex = user[4];
    var mood = user[5];
    var thumb = user[6];
    var status = user[7];
    var color = user[8];
    var rd = user[9];
    var flag = user[10];
    var grad = user[11];
    var shadow = user[12];
    var border = user[13];
    var frame = user[14];
    var height = 47;
    var clean_name = name; 

    if(rank >= 89) {
        clean_name = clearEmoji(name);
    }

    if(thumb.indexOf('default') != -1) {
        var avatar = getAvatarURL() + '/default_images/' + thumb;
    } else {
        var avatar = getAvatarURL() + '/avatar/' + thumb; 
    }
    if(sex == 1) {
        var gender = 'boy';
    } else if(sex == 2) {
        var gender = 'girl';
    } else {
        var gender = 'nosex';
    }
    if(status == 2) {
        var status_html = '<i title="' + system.away + '" class="fa absent fa-circle ustatus"></i>'
    } else if(status == 3) {
        var status_html = '<i title="' + system.busy + '" class="fa gone fa-circle ustatus"></i>';
    } else {
        var status_html = '';
    }
    if(mood) {
        if(grad) {
            var mood_html = '<p class="text_xsmall bustate_white bellips">' + mood + '</p>';
        } else {
            var mood_html = '<p class="text_xsmall bustate bellips">' + mood + '</p>';
        }

    } else {
        var mood_html = '';
    }
    var gcolor = rd[0];
    var title = rd[1];
    var icon = rd[2];
    if(bot == 1) {
        var rank_html = '<i title="' + system.bot + '" class="ico_bot fab fa-android"></i>';
    } else if(icon) {
        var rank_html = '<i style="color: ' + gcolor + '" title="' + title + '" class="fa fa-' + icon + '"></i>';
    } else {
        var rank_html = '';
    }
    if(rank_html) {
        rank_html = '<div class="user_item_icon icrank">' + rank_html + '</div>';
    }
    if(flag) {
        var flag_html = '<div class="user_item_flag"><img src="' + getStorageURL() + '/flags/' + flag + '.png"></div>';
    } else {
        if(rank < 89 && bot == 0) {
            var flag_html = '<div class="user_item_flag"><img src="' + getStorageURL() + '/flags/NOFLAG2.png"></div>';
        } else {
            var flag_html = '';
        }
    }
    if(rank < 20 && bot == 0) {
        if(gender != 'nosex') {
            flag_html = '<div class="user_item_sex ' + gender + '"><i class="fa ' + ((gender == 'boy') ? 'fa-mars' : 'fa-venus') + '"></i></div>' + flag_html;
        } else {
            flag_html = '<div class="user_item_sex ' + gender + '"><i class="fa fa-ankh"></i></div>' + flag_html;
        }
    }
    if(grad) {
        var grad_class = grad;

    } else {
        var grad_class = '';
    }
    if(shadow) {
        grad_class += ' ' + shadow;
    }
    if(grad_class) {
        height += 5;
        grad_class += ' round10 margrad';
    }
    if(add_class) {
        grad_class += ' ' + add_class;
    }
    if(typeof frame != 'undefined' && frame != '') {
        var bgpath = getStorageURL() + '/images/frames/' + frame + '.webp'; // STATIC
        var t = '<div class="user_item drop_fuser ' + grad_class + '" data-uid="' + id + '" data-rank="' + rank + '" data-uname="' + name + '" data-bot="' + bot + '"><div class="user_item_frame_avatar_new"><img loading="lazy" class="user_item_frame_inner under ul_fr_av" src="' + avatar + '"><img loading="lazy" class="over2 ul_fr_bg" src="' + bgpath + '">' + status_html + '</div><div class="user_item_data"><p class="username ' + color + '">' + clean_name + '</p>' + mood_html + '</div>' + rank_html + flag_html + '</div>';
        height += 46-36;
    } else if(border) {
        var t = '<div class="user_item drop_fuser ' + grad_class + '" data-uid="' + id + '" data-rank="' + rank + '" data-uname="' + name + '" data-bot="' + bot + '"><div class="user_item_avatar"><div class="grad_bigger_border ' + border + '"><img loading="lazy" class="small_user_av" src="' + avatar + '">' + status_html + '</div></div><div class="user_item_data"><p class="username ' + color + '">' + clean_name + '</p>' + mood_html + '</div>' + rank_html + flag_html + '</div>';
    } else {
        var t = '<div class="user_item drop_fuser ' + grad_class + '" data-uid="' + id + '" data-rank="' + rank + '" data-uname="' + name + '" data-bot="' + bot + '"><div class="user_item_avatar"><img loading="lazy" class="avsex ' + gender + '" src="' + avatar + '">' + status_html + '</div><div class="user_item_data"><p class="username ' + color + '">' + clean_name + '</p>' + mood_html + '</div>' + rank_html + flag_html + '</div>';
    }
    return {element: t, height: height};
}

userReload_fast = function (type) {
    if ($('#container_user:visible').length || type == 1) {
        if (type == 1) {
            var el = $('#container_user'); 
            if(!el.data('placeholder')) {
                var container = document.getElementById('container_user');
                var placeholder = '<div class="user_count" style="color:white;font-weight: bold;border-radius: 5px; padding:5px;text-align:center;background-color:green;height: 26px;"><div class="bcell">' + system.online + ' ... <span> <i class="fa fa-users fa-1x" style="color:white;"></i></span></div></div>';
                placeholder += '<div class="user_item"><div class="user_item_avatar"><div class="user_item_avatar_img placeholder"></div></div><div class="user_item_data"><p class="round10 placeholder">&nbsp;</p></div><div class="user_item_flag"><div class="user_item_flag_img placeholder"></div></div></div>'.repeat(30);
                panelIt(0, placeholder);
            } else {
                panelIt(0, false);
            }
        } 

        if ($('.drop_list:visible').length) {
            return false;
        } else {
            $('#user_search_text').text(system.searchPeople);
            $('#total_wrapper').hide();
            window.preventRightPanelHide = true;
            $.post('system/action.php', {
                token: utk,
                get_userlist: 1,
            }, function (response) {
                window.preventRightPanelHide = false;
                if(!document.getElementById('container_user')) {
                    chatRightIt($('<div id="container_user"></div>'));
                    delete window.hllist;
                }
                var users = response.online;
                var container = document.getElementById('container_user');
                $(container).data('placeholder', false);

                window.hlconfig = {
                    itemHeight: 47,
                    total: users.length + 1,
                    generate: function(row) {
                        if(row == 0) {
                            return {
                                element: $('<div class="user_count" style="color:white;font-weight: bold;border-radius: 5px; padding:5px;text-align:center;background-color:green;height: 26px;"><div class="bcell">' + response.lang.online + ' <span class="">' + users.length + '</span><span> <i class="fa fa-users fa-1x" style="color:white;"></i></span></div></div>').get(0), 
                                height: 26
                            };
                        }

                        var entry = generateUserListEntry(row, users[row - 1]);
                        return {
                            element: $(entry.element).get(0),
                            height: entry.height
                        };
                    }
                };
                if(typeof window.hllist == 'undefined') {
                    window.hllist = HyperList.create(container, hlconfig);
                } else if($('#container_user').length) {
                    hllist.refresh($('#container_user').get(0), hlconfig);
                }
                setInterval(function() {
                    var new_height = $('#chat_right_content').height() - $('#right_agora:visible').height() - $('#right_banner:visible').height() - $('#right_panel_bar').height() - $('#hide_ad_btn:visible').height();
                    if(hlconfig.height != new_height && $('#container_user').length) {
                        hlconfig.height = new_height;
                        hllist.refresh($('#container_user').get(0), hlconfig);
                    }
                }, 500);
                container.classList.add("container");
            });
        }
    }
}
