uploadPrivateHash = function(file_data, fail_callback) {
    if(!(window.FileReader && window.crypto && window.crypto.subtle)) {
        return fail_callback();
    }

    var fr = new FileReader();
    fr.onload = function(e) {
        var ab = e.target.result;
        crypto.subtle.digest({"name": "SHA-1"}, ab).then(function (hash) {
            $.post('system/file_private.php', {
                file_name: file_data.name,
                file_hash: hex(hash),
                target: $('#get_private').attr('value'),
                token: utk,
            }, function (response) {
                if(response == 333) {
                    fail_callback();
                } else {
                    uploadPrivateSuccessHandler(response);
                }
            });
        });
    }
    fr.readAsArrayBuffer(file_data);
}

