        var c = [colors[2], colors[0], colors[1]];
        for(var i = 0; i < c.length; i++) {
            grads.push('linear-gradient(' + degs[i] + 'deg, ' + c[i] + ',rgba(255,0,0,0) 70.71%)');
        }
        bg = grads.join(',');
    } else {
        var c = [colors[2], colors[1], colors[0]];
        bg = 'linear-gradient(to ' + (type == 'h' ? 'left' : 'top') + ',' + c.join(',') + ')';
    }

    $('#editprofile_tabs_background').removeClass().addClass('modal_menu').css('background', bg);
    $('#editprofile_tab_data_background').removeClass().css('background', bg);
    $('.grad_test').css('background', bg);

    for(var i = 0; i < 3; i++) {
        var el = $('.color-picker > div > input[data-id=' + (i+1) + ']');
        el.parent().css('color', colors[i]);
        el.val(colors[i]);
    }
}
